For `type: 'url'`, `resolveHref()` marks the link as "external" only when `target === '_blank'`, which causes absolute URLs (e.g. https://...) with `_self`/undefined target to be rendered with React Router `<Link>` later. That will produce incorrect navigation for external URLs. Consider treating all `url` items as real anchors (`<a href>`), or at least detect absolute URLs (http/https) and force `external: true` while keeping `<Link>` only for relative paths.
```suggestion
    case 'url': {
      const href = item.url ?? '#';
      const isAbsolute = /^https?:\/\//i.test(href);
      const external = item.target === '_blank' || isAbsolute;
      return { href, external };
    }
```

`activeAreaId` initializes to `areas[0].id` and the effect only validates existence by id, not whether the area is visible/permitted. If the first area is hidden or fails `requiredPermissions`, the area switcher will hide it but `resolvedNavigation` can still come from that hidden area. Consider selecting the first area that passes `evalVis` and `checkPerm`, and updating the effect to keep `activeAreaId` within the filtered set.
```suggestion

  const resolveFirstVisibleAreaId = (): string | null => {
    if (areas.length === 0) {
      return null;
    }

    const firstVisibleArea = areas.find((area) => {
      const isVisible = evalVis ? evalVis(area) : true;
      const hasPermission = checkPerm ? checkPerm(area) : true;
      return isVisible && hasPermission;
    });

    return firstVisibleArea ? firstVisibleArea.id : null;
  };

  const [activeAreaId, setActiveAreaId] = useState<string | null>(
    () => resolveFirstVisibleAreaId(),
  );

  const areaIds = areas.map((a) => a.id).join(',');

  const visibleAreas: NavigationArea[] = areas.filter((area) => {
    const isVisible = evalVis ? evalVis(area) : true;
    const hasPermission = checkPerm ? checkPerm(area) : true;
    return isVisible && hasPermission;
  });

  useEffect(() => {
    if (visibleAreas.length > 0) {
      setActiveAreaId((prev) =>
        visibleAreas.some((a) => a.id === prev) ? prev : visibleAreas[0].id,
      );
    } else {
      setActiveAreaId(null);
    }
  }, [schema.name, areaIds, evalVis, checkPerm, visibleAreas.length]);

  const activeArea = visibleAreas.find((a) => a.id === activeAreaId) ?? null;
```

